('cf8868f5-72d4-5b74-90c6-94d5a6704ee1'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'medium','mcq','"There are h jars of honey, m jars of mayonnaise, and p jars of peanut butter in a cupboard. If one of these jars is selected at random, which expression represents the probability of selecting either a jar of honey or a jar of peanut butter?"'::jsonb,'[{"key":"A","text":"h/(h + p)"},{"key":"B","text":"(h + p)/(h + p − m)"},{"key":"C","text":"(h + p)/(h + m + p)"},{"key":"D","text":"(h + p − m)/(h + m + p)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"panda.md","source_sha256":"e120378a8127836a41962876a763889bbb1df92d70c90242206130acfa43e008","source_question_id":"CP-c24-21","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from panda.md (CP-c24-21)."'::jsonb),
